/**
 * ER-07-02: 600-tick determinism fixture (07 §4.3, §5.11).
 *
 * The fixture is self-contained: a seeded scene of 256 mixed bodies plus one
 * vehicle and one character, driven by a fixed input trace. Two fresh worlds
 * must produce the same stateHash(); a different velocity-iteration count
 * must produce a different hash. Recorded values live in the fixture and are
 * asserted once they exist; they were generated by this test, never invented.
 */
import { readFileSync } from "node:fs";
import { beforeAll, describe, expect, test } from "vitest";
import type {
  CharacterController,
  VehicleHandle,
  WheelDesc,
} from "../../src/index.js";
import {
  DT,
  dynamicBox,
  dynamicCapsule,
  dynamicSphere,
  ground,
  init,
  makeWorld,
  staticTrimesh,
  v3,
} from "../support/world.js";

interface DeterminismFixture {
  readonly ticks: number;
  readonly seed: number;
  readonly world: {
    readonly gravity: readonly number[];
    readonly solver: {
      readonly velocityIterations: number;
      readonly positionIterations: number;
      readonly warmStarting: boolean;
      readonly substeps: 1 | 2;
    };
  };
  readonly scene: {
    readonly dynamic: {
      readonly spheres: number;
      readonly boxes: number;
      readonly capsules: number;
    };
    readonly staticTrimeshes: number;
    readonly ground: {
      readonly halfExtents: readonly number[];
      readonly top: number;
    };
    readonly vehicle: {
      readonly chassisHalfExtents: readonly number[];
      readonly chassisMass: number;
      readonly position: readonly number[];
      readonly wheels: readonly {
        readonly localPosition: readonly number[];
        readonly radius: number;
        readonly width: number;
        readonly suspensionRestLength: number;
        readonly suspensionStiffness: number;
        readonly suspensionDamping: number;
        readonly maxTravel: number;
        readonly steerable: boolean;
        readonly driven: boolean;
        readonly friction: number;
      }[];
      readonly engineForce: number;
      readonly reverseForce: number;
      readonly brakeForce: number;
      readonly maxSteerDegrees: number;
      readonly steerRateDegreesPerSecond: number;
      readonly topSpeed: number;
      readonly downforce: number;
    };
    readonly character: {
      readonly radius: number;
      readonly halfHeight: number;
      readonly position: readonly number[];
      readonly slopeLimitDegrees: number;
      readonly stepOffset: number;
      readonly snapToGround: number;
      readonly gravity: number;
      readonly movePerTick: readonly number[];
    };
    readonly input: {
      readonly vehicleThrottle: number;
      readonly vehicleSteerAmplitude: number;
      readonly vehicleSteerPeriodTicks: number;
    };
  };
  readonly recorded: {
    readonly bodyCount: number | null;
    readonly colliderCount: number | null;
    readonly runAHash: number | null;
    readonly runBHash: number | null;
    readonly changedSolver: {
      readonly velocityIterations: number;
      readonly hash: number | null;
    };
  };
}

const fixture = JSON.parse(
  readFileSync(
    new URL("../fixtures/determinism-600.json", import.meta.url),
    "utf8",
  ),
) as DeterminismFixture;

/** mulberry32: tiny, seeded, and identical on every run. */
function mulberry32(seed: number): () => number {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

interface BuiltScene {
  readonly vehicle: VehicleHandle;
  readonly character: CharacterController;
}

function buildScene(
  world: ReturnType<typeof makeWorld>,
  scene: DeterminismFixture["scene"],
): BuiltScene {
  ground(
    world,
    scene.ground.top,
    v3(
      scene.ground.halfExtents[0]!,
      scene.ground.halfExtents[1]!,
      scene.ground.halfExtents[2]!,
    ),
    { friction: 0.8 },
  );

  /* Four two-triangle trimesh pads: the trimesh shape in the mixed scene. */
  const padVertices = new Float32Array([-3, 0, -3, 3, 0, -3, 3, 0, 3, -3, 0, 3]);
  const padIndices = new Uint32Array([0, 1, 2, 0, 2, 3]);
  const padPositions = [
    [-15, 0.05, 0],
    [15, 0.05, 0],
    [0, 0.05, -15],
    [0, 0.05, 15],
  ] as const;
  for (
    let i = 0;
    i < scene.staticTrimeshes && i < padPositions.length;
    i += 1
  ) {
    const p = padPositions[i]!;
    staticTrimesh(world, v3(p[0], p[1], p[2]), padVertices, padIndices, {
      friction: 0.9,
    });
  }

  const random = mulberry32(fixture.seed);
  const colliderOptions = () => ({
    friction: 0.2 + random() * 0.6,
    restitution: random() * 0.2,
  });
  const bodyOptions = () => ({
    canSleep: false,
    linearVelocity: v3(
      (random() * 2 - 1) * 0.5,
      (random() * 2 - 1) * 0.5,
      (random() * 2 - 1) * 0.5,
    ),
  });
  const spawn = () =>
    v3((random() * 2 - 1) * 8, 2 + random() * 10, (random() * 2 - 1) * 8);

  for (let i = 0; i < scene.dynamic.spheres; i += 1) {
    dynamicSphere(
      world,
      spawn(),
      0.2 + random() * 0.3,
      bodyOptions(),
      colliderOptions(),
    );
  }
  for (let i = 0; i < scene.dynamic.boxes; i += 1) {
    dynamicBox(
      world,
      spawn(),
      v3(0.18 + random() * 0.25, 0.18 + random() * 0.25, 0.18 + random() * 0.25),
      bodyOptions(),
      colliderOptions(),
    );
  }
  for (let i = 0; i < scene.dynamic.capsules; i += 1) {
    dynamicCapsule(
      world,
      spawn(),
      0.18 + random() * 0.17,
      0.3 + random() * 0.5,
      bodyOptions(),
      colliderOptions(),
    );
  }

  const v = scene.vehicle;
  const chassis = dynamicBox(
    world,
    v3(v.position[0]!, v.position[1]!, v.position[2]!),
    v3(
      v.chassisHalfExtents[0]!,
      v.chassisHalfExtents[1]!,
      v.chassisHalfExtents[2]!,
    ),
    { mass: v.chassisMass, canSleep: false },
    { friction: 0.4 },
  );
  const wheels: WheelDesc[] = v.wheels.map((wheel) => ({
    ...wheel,
    localPosition: v3(
      wheel.localPosition[0]!,
      wheel.localPosition[1]!,
      wheel.localPosition[2]!,
    ),
  }));
  const vehicle = world.createVehicle({
    chassis: chassis.body,
    wheels,
    engineForce: v.engineForce,
    reverseForce: v.reverseForce,
    brakeForce: v.brakeForce,
    maxSteerDegrees: v.maxSteerDegrees,
    steerRateDegreesPerSecond: v.steerRateDegreesPerSecond,
    topSpeed: v.topSpeed,
    downforce: v.downforce,
  });

  const c = scene.character;
  const character = world.createCharacter({
    radius: c.radius,
    halfHeight: c.halfHeight,
    position: v3(c.position[0]!, c.position[1]!, c.position[2]!),
    slopeLimitDegrees: c.slopeLimitDegrees,
    stepOffset: c.stepOffset,
    snapToGround: c.snapToGround,
    gravity: c.gravity,
  });

  return { vehicle, character };
}

interface RunResult {
  readonly hash: number;
  readonly bodyCount: number;
  readonly colliderCount: number;
}

function runScene(velocityIterations: number): RunResult {
  const world = makeWorld({
    gravity: v3(
      fixture.world.gravity[0]!,
      fixture.world.gravity[1]!,
      fixture.world.gravity[2]!,
    ),
    solver: {
      velocityIterations,
      positionIterations: fixture.world.solver.positionIterations,
      warmStarting: fixture.world.solver.warmStarting,
      substeps: fixture.world.solver.substeps,
    },
  });
  const built = buildScene(world, fixture.scene);
  const input = fixture.scene.input;
  const steerPeriod = input.vehicleSteerPeriodTicks;
  for (let tick = 0; tick < fixture.ticks; tick += 1) {
    world.setVehicleInput(built.vehicle, {
      throttle: input.vehicleThrottle,
      steering:
        input.vehicleSteerAmplitude *
        Math.sin((2 * Math.PI * tick) / steerPeriod),
      brake: 0,
    });
    built.character.move(
      v3(
        fixture.scene.character.movePerTick[0]!,
        0,
        fixture.scene.character.movePerTick[2]!,
      ),
      DT,
    );
    world.step(DT);
  }
  const result = {
    hash: world.stateHash(),
    bodyCount: world.stats.bodyCount,
    colliderCount: world.stats.colliderCount,
  };
  world.dispose();
  return result;
}

beforeAll(async () => {
  await init();
});

describe("determinism-600 fixture", () => {
  test(
    "[ER-07-02] 600 ticks over 256 mixed bodies, a vehicle and a character hash identically twice",
    () => {
      const a = runScene(fixture.world.solver.velocityIterations);
      const b = runScene(fixture.world.solver.velocityIterations);
      expect(a.hash).toBe(b.hash);
      expect(a.bodyCount).toBe(b.bodyCount);
      expect(a.colliderCount).toBe(b.colliderCount);
      if (fixture.recorded.bodyCount !== null) {
        expect(a.bodyCount).toBe(fixture.recorded.bodyCount);
      }
      if (fixture.recorded.colliderCount !== null) {
        expect(a.colliderCount).toBe(fixture.recorded.colliderCount);
      }
      if (fixture.recorded.runAHash !== null) {
        expect(a.hash).toBe(fixture.recorded.runAHash);
      }
      if (fixture.recorded.runBHash !== null) {
        expect(b.hash).toBe(fixture.recorded.runBHash);
      }
      console.log(
        `[record determinism-600] bodyCount=${a.bodyCount} colliderCount=${a.colliderCount} runAHash=${a.hash} runBHash=${b.hash}`,
      );
    },
    300_000,
  );

  test(
    "[ER-07-02] a different solver velocity-iteration count changes the hash",
    () => {
      const baseline = runScene(fixture.world.solver.velocityIterations);
      const changed = runScene(
        fixture.recorded.changedSolver.velocityIterations,
      );
      expect(changed.hash).not.toBe(baseline.hash);
      if (fixture.recorded.runAHash !== null) {
        expect(baseline.hash).toBe(fixture.recorded.runAHash);
      }
      if (fixture.recorded.changedSolver.hash !== null) {
        expect(changed.hash).toBe(fixture.recorded.changedSolver.hash);
      }
      console.log(
        `[record determinism-600] baselineHash=${baseline.hash} changedSolver=${fixture.recorded.changedSolver.velocityIterations} changedHash=${changed.hash}`,
      );
    },
    300_000,
  );
});
